//! Parity with the `yake` package (https://github.com/INESCTEC/yake).
//!
//! `fixtures/yake_parity.rs` is generated by `fixtures/yake_parity.py`, which
//! records the package's sentence and token segmentation and its rankings.
//! [`distil::Yake`] gets the same tokens and stopwords, so the full candidate
//! list must match with every score within 1e-9, and the deduplicated top 10
//! must match in order.

// Generated; regenerate rather than reformat.
#[rustfmt::skip]
#[path = "fixtures/yake_parity.rs"]
mod fixture;

use distil::Yake;
use std::collections::{HashMap, HashSet};

fn run(ranking: &str, case: &fixture::Case) -> Vec<(String, f64)> {
    let stop: HashSet<String> = case.stopwords.iter().map(|s| s.to_string()).collect();
    let sentences: Vec<Vec<&str>> = case.sentences.iter().map(|s| s.to_vec()).collect();
    let yake = Yake::new().with_stopwords(stop);
    match ranking {
        "all" => yake.with_dedup(1.0).rank_tokens(&sentences, usize::MAX),
        "levs" => yake.with_dedup(0.9).rank_tokens(&sentences, 10),
        other => panic!("no ranking {other}"),
    }
}

#[test]
fn yake_matches_the_package() {
    let mut failures = Vec::new();
    let mut checked = 0;
    for case in fixture::CASES {
        for (ranking, want) in case.rankings {
            let got = run(ranking, case);
            assert!(!want.is_empty(), "{} {ranking}: empty reference", case.name);
            let want_score: HashMap<&str, f64> = want.iter().copied().collect();
            let got_score: HashMap<&str, f64> = got.iter().map(|(p, s)| (p.as_str(), *s)).collect();
            if got.len() != want.len() || want_score.keys().any(|p| !got_score.contains_key(p)) {
                failures.push(format!(
                    "{} {ranking}: candidates differ\n  distil {:?}\n  yake {:?}",
                    case.name,
                    got.iter().map(|(p, _)| p).collect::<Vec<_>>(),
                    want.iter().map(|(p, _)| p).collect::<Vec<_>>()
                ));
                continue;
            }
            for (i, ((p, s), (wp, ws))) in got.iter().zip(want.iter()).enumerate() {
                let same_rank = p == wp || (want_score[p.as_str()] - ws).abs() < 1e-12;
                if (s - want_score[p.as_str()]).abs() > 1e-9 || !same_rank {
                    failures.push(format!(
                        "{} {ranking} rank {}: distil {p:?} {s}, yake {wp:?} {ws}",
                        case.name,
                        i + 1
                    ));
                }
            }
            checked += 1;
        }
    }
    assert_eq!(checked, 3 * 2);
    assert!(failures.is_empty(), "{}", failures.join("\n"));
}
